const messages: Record<Language, Messages> = { 'zh-CN': zh, 'en-US': en }
type I18nParams = Record<string, string | number>
const makeT = (language: Language) => (key: I18nKey, params?: I18nParams) => {
  const message = messages[language][key]
  if (!params) return message
  return message.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? `{${name}}`))
}

const ERROR_KEYS: Record<string, I18nKey> = {
  ROOM_NOT_FOUND: 'roomNotFound', WRONG_PASSWORD: 'wrongPassword', ROOM_PASSWORD_REQUIRED: 'roomPasswordRequired',
  ROOM_GRANT_INVALID: 'roomPasswordRequired', RATE_LIMITED: 'requestFailed', INVALID_INPUT: 'requestFailed',
  INVALID_DATA: 'requestFailed', INTERNAL: 'requestFailed', JOIN_FAILED: 'requestFailed', NOT_IN_ROOM: 'requestFailed',
  NOT_OWNER: 'requestFailed', NO_PERMISSION: 'requestFailed', SET_ROLE_FAILED: 'requestFailed', QUEUE_FULL: 'requestFailed',
  STREAM_FAILED: 'requestFailed', NO_VOTE_NEEDED: 'requestFailed', VOTE_IN_PROGRESS: 'requestFailed', ALREADY_VOTED: 'requestFailed',
  INVALID_USERNAME: 'enterUsernameAndPassword', USERNAME_TAKEN: 'usernameTaken', INVALID_CREDENTIALS: 'invalidCredentials',
  REGISTRATION_UNAVAILABLE: 'accountOperationFailed', ALREADY_REGISTERED: 'accountOperationFailed', AUTH_REQUIRED: 'accountOperationFailed',
  INVALID_PROFILE: 'accountOperationFailed', INVALID_PASSWORD: 'passwordTooShort', INVALID_IMAGE: 'avatarTypeInvalid', IMAGE_TOO_LARGE: 'avatarTooLarge',
  CREDENTIAL_CHANGE_REQUIRED: 'passwordChangeRequired', USER_NOT_FOUND: 'accountOperationFailed', LAST_ADMIN: 'accountOperationFailed',
  INVALID_UNM_URL: 'invalidUnmUrl', UNM_ADMIN_REQUIRED: 'unmAdminRequired',
}

export function getLocalizedError(error: unknown, t: (key: I18nKey, params?: I18nParams) => string): string {
  const code = typeof error === 'object' && error !== null && 'code' in error ? String(error.code) : undefined
  return code && ERROR_KEYS[code] ? t(ERROR_KEYS[code]) : t('requestFailed')
}

interface I18nStore {
  language: Language
  setLanguage: (language: Language) => void
  t: (key: I18nKey, params?: I18nParams) => string
}

export const useI18n = create<I18nStore>((set) => ({
  language: storage.getLanguage(),
  setLanguage: (language) => {
    storage.setLanguage(language)
    set({ language, t: makeT(language) })
  },
  t: makeT(storage.getLanguage()),
}))
